local db=WoWForeverIT_QuestIT.DataIT
db[86576]=db[86576] or {}
db[86576][db[86576]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ho questioni importanti da valutare, $C. Sii breve.",enHash={"d77cc3e8"}}
db[86576]=db[86576] or {}
db[86576][db[86576]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ah, mi hai portato le pietre del sole che raccolgono le arpie! Alle arpie piace accumulare oggetti luccicanti, ma non conoscono il vero valore di queste pietre. Catturando la luce abbagliante del sole, ne riflettono la maestosità e ci permettono di adornare in suo onore i nostri santuari e le nostre case con minuscole scintille di luce. Anche la luna, di notte, le illumina con la sua bellezza argentea.\n\nQueste pietre ci ricordano il legame che abbiamo con le luci dei cieli.",enHash={"5bc21697"}}
db[86757]=db[86757] or {}
db[86757][db[86757]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Temo per ciò che sarà delle nostre case se gli orchi continueranno a spingersi sempre più a fondo nelle foreste.",enHash={"3e562944"}}
db[86757]=db[86757] or {}
db[86757][db[86757]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ottimo lavoro, $N.\n\nDeploro la situazione che ci costringe a ricorrere a questo genere di violenza, ma se gli orchi non vengono fermati invaderanno Astranaar e abbatteranno l'intero bosco. Almeno possiamo riutilizzare il metallo delle loro armi rozze per costruire difese nostre.",enHash={"ccde5c29"}}
db[86784]=db[86784] or {}
db[86784][db[86784]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Benvenut$Go:a; accanto al mio fuoco, viaggiat$Gore:rice;.",enHash={"cb1a39f0"}}
db[86784]=db[86784] or {}
db[86784][db[86784]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Altra legna da ardere? È sempre la benvenuta. Terrà al caldo queste vecchie ossa nelle fredde notti delle Glades.\n\nHo già una fionda per raccogliere la legna, quindi puoi pure tenerti quel cesto.",enHash={"c4ca776d"}}
db[87288]=db[87288] or {}
db[87288][db[87288]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Che piacere rivederti! Sei qui per commerciare?",enHash={"f34f754b"}}
db[87288]=db[87288] or {}
db[87288][db[87288]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oh, sono splendide. È un peccato dover ricorrere alla violenza contro animali così maestosi, ma è importante mantenere sicure le strade, e queste pelli diventeranno bellissime coperte e scialli.\n\nEcco, lascia che ti dia qualcosa per ricordarli. È morbido e resistente insieme.",enHash={"1671ea78"}}
db[88756]=db[88756] or {}
db[88756][db[88756]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Questa guerra contro i Dark Iron non finisce mai!",enHash={"8026492d"}}
db[88756]=db[88756] or {}
db[88756][db[88756]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ah, mi hai tolto un bel peso dalla testa. Almeno i Dark Iron non potranno far rotolare un carretto-bomba contro i nostri carri... o lanciarcele con un trabucco... o farle rotolare giù dalla collina addosso a noi... o darle in pasto alle melme e poi liberare le melme vicino al nostro accampamento e dar loro fuoco.\n\nOra dobbiamo solo assicurarci che la polvere resti asciutta!\n\nGrazie!",enHash={"332b144c"}}
db[91209]=db[91209] or {}
db[91209][db[91209]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Benvenut$Go:a; tra noi, $C. È sempre incoraggiante vedere altri dei nostri girare per queste terre. Qui a Brill in molti hanno bisogno dell'aiuto di avventurieri come te. Cerca lavoro e diventa più forte nella Luce. Torna da me ogni volta che ti serve addestramento. \n\nQuando avrai dato prova di te a me e alla gente di Brill, ti darò indicazioni per la prossima tappa del tuo viaggio.\n\nVa' con la Luce, $C.",enHash={"aa5f177a"}}
db[91282]=db[91282] or {}
db[91282][db[91282]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Un'altra recluta fresca? Benvenut$Go:a; a Tyr's Watch, $Gfratello:sorella;.",enHash={"89526053"}}
db[91723]=db[91723] or {}
db[91723][db[91723]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Fammi sapere quando hai finito, così posso riprovare a calibrare i miei strumenti.",enHash={"396e91a1"}}
db[91723]=db[91723] or {}
db[91723][db[91723]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ben fatto, amic$Go:a; mi$Go:a;. Lascia che riprovi con le mie calibrazioni...",enHash={"a805b71d"}}
db[91725]=db[91725] or {}
db[91725][db[91725]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Hai trovato le provviste?",enHash={"68cc1b5e"}}
db[91725]=db[91725] or {}
db[91725][db[91725]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oh, che sollievo! Sembra che ci sia tutto. Grazie!",enHash={"38ed878b"}}
db[91732]=db[91732] or {}
db[91732][db[91732]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sei già stat$Go:a; alla miniera?",enHash={"2d021fab"}}
db[91732]=db[91732] or {}
db[91732][db[91732]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oh, molto bene. Vedi come brilla? Davvero, non le fanno più come una volta.",enHash={"f3fa1f4b"}}
db[91733]=db[91733] or {}
db[91733][db[91733]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Hai trovato le provviste?",enHash={"68cc1b5e"}}
db[91733]=db[91733] or {}
db[91733][db[91733]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Sei un po' bagnat$Go:a;, $N. Mi dispiace. Ma grazie per aver recuperato le provviste.",enHash={"df9b61a9"}}
db[91920]=db[91920] or {}
db[91920][db[91920]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Oh. Sei tornat$Go:a;?",enHash={"8104b8be"}}
db[91920]=db[91920] or {}
db[91920][db[91920]["reward"] and "reward#wowhead20261030" or "reward"]= {it="La pozione non ha funzionato? Certo che non ha funzionato. Mi hai portato cuori insufficienti. La ricetta ne richiede chiaramente sei. Tu ne hai portati tre.\n\nTuttavia, confesso che finora non avevo considerato possibili usi per le parti di murloc...\n\n<Renferrel prende gli occhi.>\n\nPosso permettermi di sacrificare alcuni dei miei cuori per far tornare in forze il tuo Deathstalker.",enHash={"2d80750e"}}
db[91921]=db[91921] or {}
db[91921][db[91921]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sei tornat$Go:a;! Cominciavo a rassegnarmi all'idea di trasformarmi in un ghoul.",enHash={"3b481492"}}
db[91921]=db[91921] or {}
db[91921][db[91921]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Quinn prende la pozione e la beve.>\n\nSì, sento che fa effetto. Presto potrò rimettermi in viaggio.\n\nMi hai fatto un grande favore, $N.",enHash={"01eb4357"}}
db[92401]=db[92401] or {}
db[92401][db[92401]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ciò che ti ho chiesto non era giusto, e non sarebbe stato ingiusto se te ne fossi semplicemente andat$Go:a;. Grazie, straniero. Non posso ricambiarti come meriteresti, ma spero che una di queste cose ti sia gradita.\n\nSpero che le nostre strade si incrocino di nuovo senza tanto dolore.",enHash={"84c57eb0"}}
db[92421]=db[92421] or {}
db[92421][db[92421]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cosa resta del Flagello invasore? Sei riuscit$Go:a; a trovare pezzi di ricambio adatti?",enHash={"76ddecb6"}}
db[92421]=db[92421] or {}
db[92421][db[92421]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Che chi cade in disgrazia presso la Regina Banshee incontri la nostra giustizia!\n\nCon questi pezzi, i nostri fratelli e sorelle hanno la speranza di vedere un altro giorno. Rendi onore al Capitano Bandarion.",enHash={"3628f506"}}
db[92432]=db[92432] or {}
db[92432][db[92432]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Vedo che Jacques è riuscito a trovare aiuto.\n\nAnche se non è propriamente permesso, non possiamo lasciare che l'orgoglio ci faccia respingere degli alleati nell'ora del bisogno. Non farti ingannare dalle guardie. La situazione è tutt'altro che sotto controllo.",enHash={"b4c31599"}}
db[92456]=db[92456] or {}
db[92456][db[92456]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Allora? Ce l'hai?",enHash={"5a54095b"}}
db[92456]=db[92456] or {}
db[92456][db[92456]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questo è... non proprio ciò che avevo in mente.\n\nChiaramente la città sta passando più guai di quanto mi aspettassi. Ma ciò che hai trovato è altrettanto affascinante, se non di più.\n\nDirei che non sei così fastidios$Go:a; come pensavo. Buon lavoro.",enHash={"60681e73"}}
db[92457]=db[92457] or {}
db[92457][db[92457]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grazie, $N, questi progressi aiuteranno a mantenere Dalaran al sicuro.",enHash={"f1d27109"}}
db[92458]=db[92458] or {}
db[92458][db[92458]["progress"] and "progress#wowhead20261030" or "progress"]= {it="A che serve il nostro orgoglio se non resta in piedi una città di cui essere orgogliosi?",enHash={"6a8e3aee"}}
db[92458]=db[92458] or {}
db[92458][db[92458]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Non so cosa tu abbia visto lassù, $N, ma non ha importanza. Ciò che conta ora è contenere questa particella e mettere fine a questa follia.\n\nHai fatto bene la tua parte. Ora il resto spetta a noi.",enHash={"03f3a4ce"}}
db[92459]=db[92459] or {}
db[92459][db[92459]["progress"] and "progress#wowhead20261030" or "progress"]= {it="L'Arcimaga Modera parla molto bene di te. Cosa ti porta a Dalaran?",enHash={"ca3ae603"}}
db[92459]=db[92459] or {}
db[92459][db[92459]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Dove l'hai trovato? Nel salotto?\n\n<L'espressione dell'Arcimaga Celindra si incupisce per un istante, prima che ritrovi la compostezza.>\n\nCredo sia meglio che tu lo scacci dai tuoi pensieri, amic$Go:a;. Per ora il Kirin Tor accoglie volentieri $Gun:una; $C competente come te. Benvenut$Go:a; a Dalaran.",enHash={"764ac1cc"}}
db[92481]=db[92481] or {}
db[92481][db[92481]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Salve, $N. Sono lieto di avere il privilegio di far progredire i tuoi studi magici.",enHash={"47342231"}}
db[92481]=db[92481] or {}
db[92481][db[92481]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Lascia che ti guardi. Sì, credo che diventerai $Gun:una; giovane $C eccellente. Il potere arcano si è affievolito tra la nostra gente, ma c'è chi cerca di riscoprire molto di ciò che abbiamo perduto nei millenni trascorsi quassù tra le nuvole. Sono certo che guiderai questa ricerca senza fine della conoscenza arcana, e che alla fine ci renderai orgogliosi.\n\nParla di nuovo con me se desideri compiere i tuoi prossimi passi.",enHash={"eb66d3bd"}}
db[92482]=db[92482] or {}
db[92482][db[92482]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<Tai'ree ti saluta con un breve cenno del capo.>",enHash={"326ae004"}}
db[92482]=db[92482] or {}
db[92482][db[92482]["reward"] and "reward#wowhead20261030" or "reward"]= {it="La via del $C è irta di pericoli, e solo chi ha i sensi più acuti e i riflessi più pronti può prosperare nelle terre selvagge. Ti guardo e mi rivedo quando stavo davanti al mio mentore, tanti anni fa. Credo che tu abbia ciò che serve, ma alla fine dipende solo da te.\n\nParla di nuovo con me se desideri compiere i tuoi prossimi passi.",enHash={"7ef21687"}}
db[92489]=db[92489] or {}
db[92489][db[92489]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Una creatura di puro mana? Qualunque cosa causi questo disturbo è più potente di quanto suggerissero i primi rapporti.\n\nIl tuo aiuto ha fatto guadagnare loro tempo prezioso e ha ricordato al Kirin Tor chi sono i suoi alleati. Buon lavoro, $N.",enHash={"4b492cc8"}}
db[92706]=db[92706] or {}
db[92706][db[92706]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cosa posso fare per te, $R?",enHash={"cafa1b8c"}}
db[92706]=db[92706] or {}
db[92706][db[92706]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Finalmente qualcuno ha ucciso quella bestia! Lo sai quanto è difficile mandare un equipaggio in acqua quando tutti in città gridano \"Squalo!\" in continuazione?\n\nStasera potrei mettere la pinna di quel mostro in una zuppa per cena, giusto per avere l'ultima parola.",enHash={"172020e3"}}
db[92840]=db[92840] or {}
db[92840][db[92840]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Spesso faccio fatica a distinguere tra i Windshaper e gli Al'Aketh, se non per il fatto che gli uni sono più apertamente violenti degli altri. Ugualmente schiavi delle loro convinzioni sbagliate, sono entrambi pericolosi se lasciati a se stessi.\n\nVedono il nostro desiderio di comprendere meglio questo regno e la sua magia come una profanazione delle loro tradizioni. La loro ristrettezza mentale è il motivo per cui la nostra missione è così importante. Se non noi, chi avrà il coraggio di salvare Zephras?",enHash={"c3f2f3f4"}}
db[92840]=db[92840] or {}
db[92840][db[92840]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Non avrei voluto versare sangue Windshaper, ma la colpa di questo conflitto insensato ricade solo su di loro. Cercavamo di raccogliere informazioni pacificamente, e loro hanno risposto con la violenza.\n\nPurtroppo la voce si è sparsa e i Windshaper lo chiamano già un 'massacro'. Non oserebbero vendicarsi qui a Valanaar, ma di certo non dimenticheranno.\n\n$N, sei stat$Go:a; di enorme aiuto all'High Order. Grazie.",enHash={"b6cd9fc0"}}
db[92947]=db[92947] or {}
db[92947][db[92947]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<Hyusaa ti fa un cenno del capo.>",enHash={"e98fafbd"}}
db[93680]=db[93680] or {}
db[93680][db[93680]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cosa hai trovato? Un tomo antico? Una reliquia segreta?",enHash={"bf14a114"}}
db[93680]=db[93680] or {}
db[93680][db[93680]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Una chiave delle fogne? Beh, per fortuna non sarò io a doverla usare.\n\nMa abbiamo del lavoro da fare prima che sia sicuro usarla.",enHash={"faadcdfe"}}
db[93737]=db[93737] or {}
db[93737][db[93737]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grazie per aver recuperato questi materiali. Immagino che alcuni non siano stati affatto facili da ottenere. \n\nCon questi pezzi posso rimettere in funzione il costrutto. Da lì possiamo solo sperare che la sua memoria sia intatta e che possa dirci chi ha preso i suoi componenti.",enHash={"6c575cb1"}}
db[93739]=db[93739] or {}
db[93739][db[93739]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Dunque sei tornat$Go:a;. Spero che tu abbia imparato molto nel tuo viaggio.\n\nA quanto so, la tua gente si sta ancora stabilendo a Mulgore. Mentre li aspetti, ti incoraggio a esplorare il territorio intorno a Orgrimmar. Le Barrens in particolare hanno sempre bisogno di avventurieri volenterosi come te.",enHash={"ed7d19e6"}}
db[93951]=db[93951] or {}
db[93951][db[93951]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Raccogliere piume per i nostri capelli potrebbe sembrare una frivolezza un po' vanitosa. Eppure, anche in tempi come questi, bisogna accogliere le piccole gioie il più possibile. \n\nSe anche una sola cosa che creo porta gioia a qualcuno, la considererò una bella giornata. Grazie per avermele portate e per avermi aiutato a portare un po' di gioia su Zephras.",enHash={"edcbd438"}}
db[94006]=db[94006] or {}
db[94006][db[94006]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Dunque desideri abbracciare la via dell'artiglio, $Gragazzo:ragazza;? Molto bene. Parliamone.",enHash={"da3b7ab3"}}
db[94013]=db[94013] or {}
db[94013][db[94013]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Imparerai, $N, e un giorno sarai $Gun grande:una grande; $C.",enHash={"e1d1af3d"}}
db[94013]=db[94013] or {}
db[94013][db[94013]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Eccellente, $N! Impari davvero in fretta. Ora che conosci le basi, posso insegnarti a stringere un legame duraturo con un compagno animale.\n\nVa' con questa conoscenza e prospera. Sii $Gil:la; $C di cui Zephras Isle ha bisogno.",enHash={"dce9c252"}}
db[94050]=db[94050] or {}
db[94050][db[94050]["reward"] and "reward#wowhead20261030" or "reward"]= {it="$Gun:una; $C alle prime armi, vedo. Sì, posso trasmetterti le abilità che ti servono per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, $N, rispetta sempre l'equilibrio e vivi in reverenza della natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.",enHash={"331b8374"}}
db[94216]=db[94216] or {}
db[94216][db[94216]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sei qui per...\n\n<Ziz si guarda intorno sospettoso nella sua minuscola capanna e abbassa la voce.>\n\nL'elisir?",enHash={"276d22b3"}}
db[94216]=db[94216] or {}
db[94216][db[94216]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Ziz continua a parlare sottovoce.>\n\nNon ho intenzione di raccontarti tutta la storia di come sono finito in questa situazione, ma eccoti un consiglio.\n\nA volte, per fare colpo sul tuo nuovo capo, basta prendersi il merito del lavoro di qualcun altro. Quindi tu mi consegni l'elisir, e io racconterò quanto sangue, sudore e lacrime ci ho messo per prepararlo.\n\nÈ un lavoro nuovo, va bene? Devo fare una buona prima impressione!",enHash={"9c5e8515"}}
db[94222]=db[94222] or {}
db[94222][db[94222]["progress"] and "progress#wowhead20261030" or "progress"]= {it="AHHH! Oh... Me pensato tu sembra mostro di melma.",enHash={"d9f3e673"}}
db[94222]=db[94222] or {}
db[94222][db[94222]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questo mio nuovo martello?\n\n<Il peon ti strappa l'arma di mano prima che tu abbia l'occasione di rispondere. La agita all'impazzata nella tua direzione, mancando di poco il tuo cranio.>\n\nSÌ! Ora me combatte. Questo non perde, no no.\n\nPrendi questo. Non so a cosa serve, ma è caduto da creatura di melma.",enHash={"21c15b83"}}
db[94468]=db[94468] or {}
db[94468][db[94468]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sì, $N? Cos'hai lì?",enHash={"c6deb4c4"}}
db[94468]=db[94468] or {}
db[94468][db[94468]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Per la barba di Madoran, il tuo spirito arde più luminoso di qualsiasi torcia io abbia mai visto, $N, ed è qualcosa di cui essere fier$Go:a;.\n\nContinua su questa strada, e gli elementi si piegheranno alla tua volontà. La nostra gente verrà da te in cerca di saggezza e guida. Lascia dunque che sia il primo a farti le mie più sentite congratulazioni, e a consegnarti il tuo nuovo totem. Te lo sei guadagnato, figli$Go:a; della fiamma.",enHash={"da9f560f"}}
db[94491]=db[94491] or {}
db[94491][db[94491]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Il volto di Lotheluum si riempie di autentico terrore mentre racconti gli eventi della tana dei druidi.>\n\nMi... mi dispiace, $N. Ho bisogno solo di un momento. Non ho parole per descrivere questa perdita.\n\nSono davvero notizie gravi. Se questa missiva non è falsa, allora qui a Valanaar abbiamo nel migliore dei casi un complice e nel peggiore un traditore. La porterò subito all'High Elder! Non lascerò che il sacrificio dei miei compagni sia stato vano.",enHash={"4361e976"}}
db[94638]=db[94638] or {}
db[94638][db[94638]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ciò che ti chiedo non è un compito facile. Fatti forza del tuo coraggio e torna da me quando l'impresa sarà compiuta.",enHash={"cbe65f38"}}
db[94638]=db[94638] or {}
db[94638][db[94638]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Il dolore che provo per la sua perdita è incommensurabile, ma è ciò che l'equilibrio richiede. Hai dimostrato la determinazione di perseverare, anche quando viene chiesto un prezzo terribile.\n\nHai fatto bene, $C. Ti concederò la benedizione di assumere la forma dei miei simili. Sii un faro per chi non ha la forza di perseverare e $Gun difensore:una difenditrice; di chi è nel bisogno.\n\nOra va', e abbraccia la via dell'artiglio, $Gragazzo:ragazza;.",enHash={"767c64ec"}}
db[94978]=db[94978] or {}
db[94978][db[94978]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Imparerai, $N, e un giorno sarai $Gun grande:una grande; $C.",enHash={"e1d1af3d"}}
db[94978]=db[94978] or {}
db[94978][db[94978]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ben addomesticato, $N! Stai già diventando espert$Go:a;.",enHash={"6c19e855"}}
db[94979]=db[94979] or {}
db[94979][db[94979]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Imparerai, $N, e un giorno sarai $Gun grande:una grande; $C.",enHash={"e1d1af3d"}}
db[94979]=db[94979] or {}
db[94979][db[94979]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Sei già tornat$Go:a;! Che velocità, $N!",enHash={"d1005920"}}
db[95036]=db[95036] or {}
db[95036][db[95036]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Confida nella Luce perché guidi la tua lama. Però la Luce ha bisogno di una buona lama da guidare.",enHash={"5ecc0eef"}}
db[95036]=db[95036] or {}
db[95036][db[95036]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ora che abbiamo i materiali che ci servono, ci manca solo un fabbro che forgi la lama per noi. Credo di conoscere proprio il fabbro giusto.",enHash={"885012ab"}}
db[95041]=db[95041] or {}
db[95041][db[95041]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Come procede il recupero dei dati?",enHash={"a1d4ca97"}}
db[95041]=db[95041] or {}
db[95041][db[95041]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Queste schede sembrano un po' umide... ma posso lavorarci! Grazie, $N!",enHash={"5c8eb178"}}
db[95195]=db[95195] or {}
db[95195][db[95195]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sembri portare un pesante fardello, $N. Di che si tratta?",enHash={"b2b97b5b"}}
db[95195]=db[95195] or {}
db[95195][db[95195]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Il tuo istinto di portarmeli non era infondato. Quando Lordaeron cadde per mano del Flagello, molti fuggirono per rifugiarsi qui a Stormwind. Probabilmente restano in pochi a poter reclamare queste insegne di persona.\n\nIl tuo senso del dovere verso Stormwind merita un encomio, $N. Comincerò subito a consegnare questi pegni ai parenti più stretti.",enHash={"ba49a61c"}}
db[95204]=db[95204] or {}
db[95204][db[95204]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai lì, $C? Un bocconcino gustoso?",enHash={"a25e103a"}}
db[95204]=db[95204] or {}
db[95204][db[95204]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Oran morde lo stemma per accertarne l'autenticità.>\n\nGuarda un po'. Un'autentica reliquia della nostra patria. E quasi intatta, per giunta. Dobbiamo stare particolarmente attenti con questa.\n\nGrazie per il tuo aiuto nel ricostruire la nostra storia, $C. Farò in modo che ce ne prendiamo buona cura.",enHash={"1b5d7800"}}
db[95212]=db[95212] or {}
db[95212][db[95212]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sembri infreddolit$Go:a;, $C. Come va la caccia?",enHash={"d5729a3d"}}
db[95212]=db[95212] or {}
db[95212][db[95212]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Queste pelli diventeranno selle eccellenti. Hai reso onore all'Alleanza, $C!",enHash={"b142c30e"}}
db[95213]=db[95213] or {}
db[95213][db[95213]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai lì?",enHash={"df2f7953"}}
db[95213]=db[95213] or {}
db[95213][db[95213]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Il $R impallidisce quando vede il barile vuoto.>\n\n...Dove l'hai trovato?",enHash={"e1b4b38e"}}
db[95214]=db[95214] or {}
db[95214][db[95214]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Spero che tu abbia buone notizie per me?",enHash={"0bfd8516"}}
db[95214]=db[95214] or {}
db[95214][db[95214]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Dovrebbe essere tutta la polvere rubata. Grazie, $C.\n\nTi prego, accetta questa ricompensa e... ti sarei grato se non parlassi a nessuno di questo piccolo incidente.",enHash={"9882b5f6"}}
db[95216]=db[95216] or {}
db[95216][db[95216]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Qualunque sciocco può dirti che il metodo di trasmissione più efficace sarà sempre attraverso il sangue.\n\nDevo vedere questo ceppo con i miei occhi!",enHash={"04e311db"}}
db[95216]=db[95216] or {}
db[95216][db[95216]["reward"] and "reward#wowhead20261030" or "reward"]= {it="L'hai ucciso??\n\nHmmph. Per tua fortuna, questo icore dovrebbe bastare per ricostruirne le proprietà. Non vorrai diventare nemic$Go:a; della Royal Apothecary Society.\n\nSparisci dalla mia vista!",enHash={"19bcabd8"}}
db[95314]=db[95314] or {}
db[95314][db[95314]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Confido che tu non ti sia pers$Go:a;?",enHash={"e225cca3"}}
db[95314]=db[95314] or {}
db[95314][db[95314]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Dici che c'è del male a Shadowvale? Lo ammetto, non mi sorprende. La gente della foresta era un tipo strano, e non amava i visitatori. Alcuni credono che la Whispering Forest stessa sia maledetta, e che l'elisir distillato dalle sue radici porti con sé la stessa maledizione...\n\n...ma basta con superstizioni e dicerie, $N. Grazie per gli elisir. Ecco, prendi questo come pagamento.",enHash={"2ec88090"}}
db[95350]=db[95350] or {}
db[95350][db[95350]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Lok-tar, $C. Sono Thrall, Capoguerra dell'Orda.\n\nUn messaggero dell'Earthen Ring mi aveva detto di aspettare dei membri dei Windshaper, ed eccoti qui. Non mi sarei aspettato di vedere un elfo alto davanti a me qui a Orgrimmar, ma l'Orda ti accoglierà comunque come nostr$Go:a; ospite.\n\nHai la mia benedizione per viaggiare nelle terre dell'Orda. Va' con onore, Windshaper.",enHash={"4a039da8"}}
db[95494]=db[95494] or {}
db[95494][db[95494]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Come va la caccia?",enHash={"29108c63"}}
db[95494]=db[95494] or {}
db[95494][db[95494]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Sì, queste dovrebbero andare benissimo. Ho un accordo con un conciatore del posto: gli consegno queste pelli grezze in cambio di vari articoli in cuoio finiti che uso per il mio mestiere. \n\nNon sono mai venuto meno alla mia parte dell'accordo, e non intendo cominciare ora, nemmeno con la mia ferita.",enHash={"26fde9c9"}}
db[95495]=db[95495] or {}
db[95495][db[95495]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Salve, $C. Cosa ti porta oggi fin quassù nella mia proprietà?",enHash={"1ffa0c78"}}
db[95495]=db[95495] or {}
db[95495][db[95495]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Allora ti manda Vrang? Molto bene. Ti ringrazio per avermi consegnato queste pelli. Peccato che Vrang non abbia potuto fare il viaggio di persona. C'è una questione di cui vorrei parlargli.",enHash={"e94463fd"}}
db[95507]=db[95507] or {}
db[95507][db[95507]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<Vrang ti rivolge un grugnito mentre ti avvicini.>",enHash={"6b96c7d8"}}
db[95507]=db[95507] or {}
db[95507][db[95507]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grazie per il tuo aiuto, $C. Cominciavo a chiedermi se stanotte sarei dovuto andare a letto affamato per colpa di questa maledetta ferita alla gamba.",enHash={"7c7e9716"}}
db[95508]=db[95508] or {}
db[95508][db[95508]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Beh, sembra che siamo tutti vivi. Io... sapevo che un giorno il passato mi avrebbe raggiunto. Ti sono debitore per il tuo aiuto oggi.\n\nTi prego, prendi questo. Non è molto, ma è il minimo che possa fare.\n\nBuon viaggio, $C.",enHash={"635116e4"}}
db[95621]=db[95621] or {}
db[95621][db[95621]["progress"] and "progress#wowhead20261030" or "progress"]= {it="I resti della flotta di Daelin Proudmoore che ancora battono la sua bandiera sono marci e barbari quanto lo era l'ammiraglio stesso prima di morire.\n\nNon so perché siano così lontani da Tiragarde, ma non può essere niente di buono.",enHash={"06a3f8fa"}}
db[95621]=db[95621] or {}
db[95621][db[95621]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Quindi cercano un disertore... Beh, sembra che il passato mi abbia finalmente raggiunto.",enHash={"e573596e"}}
db[95646]=db[95646] or {}
db[95646][db[95646]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Queste acque ospitano una vita unica, in una salamoia che dà e toglie in egual misura.",enHash={"91f6a379"}}
db[95646]=db[95646] or {}
db[95646][db[95646]["reward"] and "reward#wowhead20261030" or "reward"]= {it="È peggio di quanto temessi. Un'energia antica si sta risvegliando. Sarebbe molto saggio che tu avvertissi i tuoi zelanti scavatori di smettere di scavare, per la loro stessa sicurezza.",enHash={"e213d6c9"}}
db[95774]=db[95774] or {}
db[95774][db[95774]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ora ho solo ricordi, ma costruirò un tributo a Olgra perché non svaniscano mai.",enHash={"a943b4e9"}}
db[95774]=db[95774] or {}
db[95774][db[95774]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Metterò questi ornamenti presso il memoriale di mia moglie, così non la dimenticherò mai. Il mio sangue ribollirà sempre di vendetta!\n\nMi hai fatto... ci hai fatto... un grande favore, $N.",enHash={"27f5b2ae"}}
db[95883]=db[95883] or {}
db[95883][db[95883]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<La pietra delle offerte è sinistramente immobile.>",enHash={"73f4d223"}}
db[95883]=db[95883] or {}
db[95883][db[95883]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<L'anima tormentata sprigiona un'energia malvagia in presenza della pietra delle offerte.\n\nSembra che tu sia più vicin$Go:a; a compiere il rituale.>",enHash={"620e21e3"}}
db[95884]=db[95884] or {}
db[95884][db[95884]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Strani attrezzi e oggetti ingombrano la superficie ruvida della pietra.\n\nQuesta è sicuramente la pietra delle offerte menzionata nel biglietto.>",enHash={"f8ab5ae1"}}
db[95885]=db[95885] or {}
db[95885][db[95885]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<La pietra delle offerte è sinistramente immobile.>",enHash={"73f4d223"}}
db[95885]=db[95885] or {}
db[95885][db[95885]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Ora la pietra delle offerte è inerte. Sembra che il tuo rituale l'abbia prosciugata del suo potere. A quale scopo, non lo sai, ma ormai è finita.\n\nLa pietra ruvida si crepa e si sgretola, ormai priva di scopo.\n\nQualcosa luccica tra i resti...>",enHash={"05bceef7"}}
db[95981]=db[95981] or {}
db[95981][db[95981]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Da quando la barriera intorno a Dalaran è caduta, il Kirin Tor tiene le strade in una morsa ferrea. Sono paranoici per qualcosa, questo è certo.\n\nPer ora, comunque, il perché non ha importanza.",enHash={"42c9bb30"}}
db[95998]=db[95998] or {}
db[95998][db[95998]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Avere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.",enHash={"d6d108af"}}
db[95999]=db[95999] or {}
db[95999][db[95999]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai lì, $R?",enHash={"3c2370d7"}}
db[95999]=db[95999] or {}
db[95999][db[95999]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ottimo lavoro, $N! L'Incinerator Gar'im si preparava a rafforzare le difese di Stonewatch Keep. Con questa vittoria potremmo ancora riuscire a riconquistare la fortezza!",enHash={"2d1dfb88"}}
db[96137]=db[96137] or {}
db[96137][db[96137]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai lì?",enHash={"b728b96c"}}
db[96137]=db[96137] or {}
db[96137][db[96137]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ira? Ne sei sicur$Go:a;? Sembra che quella donna fosse quasi un fantasma già prima di morire. Mi sorprende che tu l'abbia trovata.\n\nStai tranquill$Go:a;, avrò grande cura di questo pugnale.",enHash={"c2c50afe"}}
db[96138]=db[96138] or {}
db[96138][db[96138]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sì, di che si tratta?",enHash={"87528bdf"}}
db[96138]=db[96138] or {}
db[96138][db[96138]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Merrick Valor, dici? Povero ragazzo, voleva sempre mettersi alla prova. È stato un peccato ciò che è successo a lui e alla sua famiglia.\n\nGrazie per avermelo portato, $N. Forse può gettare un po' di luce in più sulla storia di Raven Hill.",enHash={"d5be3ca6"}}
db[96139]=db[96139] or {}
db[96139][db[96139]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Hai trovato qualcosa? Non ci spero molto.",enHash={"27d21c46"}}
db[96139]=db[96139] or {}
db[96139][db[96139]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questo tomo sembra parlare della famiglia Valor. Credo di aver sentito parlare di alcuni di loro. Brava gente. Non sono sicuro che meritino un intero libro su di loro.\n\nTi farò una copia del tomo. Se durante i tuoi viaggi vedi qualcos'altro che li riguarda, sarò felice di prenderlo io.",enHash={"eec65f43"}}
db[96390]=db[96390] or {}
db[96390][db[96390]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questi Dark Iron saranno pure nostri cugini, ma non sono famiglia, questo è certo. Non verso lacrime per le disgrazie che capitano a quelli che si allontanano troppo da quella loro montagna maledetta.\n\nSperiamo che basti a dissuaderli da altre incursioni in queste terre.",enHash={"0a8a6d36"}}
db[96391]=db[96391] or {}
db[96391][db[96391]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Oh, e questo cos'è?",enHash={"a22bf0e7"}}
db[96391]=db[96391] or {}
db[96391][db[96391]["reward"] and "reward#wowhead20261030" or "reward"]= {it="A giudicare da questa mappa, sembra proprio che questi Dark Iron stiano progettando una sorta di incursione nelle volte sotto Ironforge. La banda che hai sbaragliato a est dev'essere una forza di ricognizione.\n\nGrazie per avermela portata. Se ci sbrighiamo, potremmo anticiparli, qualunque sia il loro obiettivo laggiù.",enHash={"0d54b466"}}
db[96392]=db[96392] or {}
db[96392][db[96392]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Farsight può mostrarti tante cose, anche cose che preferiresti non vedere.",enHash={"fbe3cde3"}}
db[96392]=db[96392] or {}
db[96392][db[96392]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Allora, ora vedi, $C? Sono fitti come scarafaggi, e quelli sono solo quelli che vediamo dal cielo.\n\nSembri un tipo abbastanza robusto. Che ne dici di un po' di violenza?",enHash={"ba62b7bc"}}
db[96393]=db[96393] or {}
db[96393][db[96393]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Di cosa hai bisogno, cittadin$Go:a;?",enHash={"953d537c"}}
db[96393]=db[96393] or {}
db[96393][db[96393]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Un'incursione dei Dark Iron, proprio sotto i nostri piedi? Beh, mi sollevo nel sapere che il comandante Dark Iron è stato eliminato.\n\nLe guardie entreranno a ripulire il resto della marmaglia. Faremo in modo che le brecce vengano sigillate e i livelli inferiori rinforzati, così che nessun'altra incursione sia possibile.\n\nGrazie per il tuo servizio a Ironforge, $C. Prendi questo come piccolo segno della mia gratitudine. Oh, e se rivedi quel vecchio abbracciarocce Wildhammer di Farsen, digli di venirmi a fare una visita come si deve.",enHash={"3fa4e96f"}}
db[96408]=db[96408] or {}
db[96408][db[96408]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Salve, amic$Go:a;. Come va?",enHash={"63d85ebd"}}
db[96604]=db[96604] or {}
db[96604][db[96604]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Avere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.",enHash={"190a7241"}}
db[96604]=db[96604] or {}
db[96604][db[96604]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ora che abbiamo imparato le basi, perché non vai a imparare una professione dagli addestratori del villaggio qui vicino? Ti insegneranno anche a creare un elemento da accampamento adatto alla tua nuova professione.",enHash={"a6ab1e94"}}
