db[96626][db[96626]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Un buon fuoco da campo è la base di ogni buon accampamento.",enHash={"029d9016"}}
db[96652]=db[96652] or {}
db[96652][db[96652]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sei qui per imparare ad accamparti nelle terre selvagge?",enHash={"8f5e8f17"}}
db[96652]=db[96652] or {}
db[96652][db[96652]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Quello è il mio diario? Lo cercavo da un po'. Grazie, $C.\n\nEhi, anche tu hai l'aria di $Gun avventuriero:un'avventuriera;. Ti piacerebbe imparare ad accamparti?",enHash={"81c64fc4"}}
db[96655]=db[96655] or {}
