db[96655]=db[96655] or {}
db[96655][db[96655]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nAumenta la tua abilità in cucina e potresti imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi per arredare i tuoi accampamenti da altri addestratori di professioni, se te la cavi nelle loro arti.",enHash={"eb4b2c4c"}}
