db[96661][db[96661]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Un buon fuoco da campo è la base di ogni buon accampamento.",enHash={"029d9016"}}
db[96661]=db[96661] or {}
db[96661][db[96661]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Ciò che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nAumenta la tua abilità in cucina e potresti imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi per arredare i tuoi accampamenti da altri addestratori di professioni, se te la cavi nelle loro arti.",enHash={"eb4b2c4c"}}
db[96781]=db[96781] or {}
db[96781][db[96781]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Chissà cosa cercano in quelle rovine?",enHash={"ab8e6a88"}}
db[96781]=db[96781] or {}
db[96781][db[96781]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Sembra che tu abbia le dita svelte, $N. Molto bene.",enHash={"2634338f"}}
db[96783]=db[96783] or {}
db[96783][db[96783]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Prendendo l'uniforme, ti prepari per la prossima parte della tua missione.>",enHash={"2e7d72e8"}}
db[96800]=db[96800] or {}
db[96800][db[96800]["progress"] and "progress#wowhead20261030" or "progress"]= {it="A volte ho l'impressione che questa tesi sia maledetta.",enHash={"ddaf344c"}}
db[96800]=db[96800] or {}
db[96800][db[96800]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oh, hai dovuto uccidere Doan per riavere il libro? Oh no...\n\n... beh, comunque, tutto è bene quel che finisce bene! Grazie per averlo rimesso al suo posto e per avermi aiutato a finire la mia tesi. Sono assolutamente convinto che riportare in vita l'arte perduta della magia runica dei nani sia alla nostra portata, e intendo dimostrarlo!\n\nSe solo potessi entrare a Grim Batol e studiare di persona le antiche incisioni runiche...\n\nUn giorno, forse.",enHash={"34f3122d"}}
db[96822]=db[96822] or {}
db[96822][db[96822]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Hai fatto ciò che ti ho chiesto?",enHash={"2180e715"}}
db[96822]=db[96822] or {}
db[96822][db[96822]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questi guerrieri saranno sempre ricordati, $N. Te ne sei assicurat$Go:a;.",enHash={"af4cab91"}}
db[96873]=db[96873] or {}
db[96873][db[96873]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai per me, $N?",enHash={"1c407e14"}}
db[96873]=db[96873] or {}
db[96873][db[96873]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Bel lavoro. Peccato per i troll uccisi, ma ora che gli incantesimi di vincolo sono stati rimossi, i loro spiriti possono riposare.",enHash={"3c147471"}}
db[96874]=db[96874] or {}
db[96874][db[96874]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sì?",enHash={"00388a38"}}
db[96874]=db[96874] or {}
db[96874][db[96874]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Queste spine sono più dure di quanto mi aspettassi, $N! Lavorarle potrebbe non essere facile come pensavo... ma continuerò a provarci!",enHash={"41b59373"}}
db[96876]=db[96876] or {}
db[96876][db[96876]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Serve qualcosa?",enHash={"f85babcc"}}
db[96876]=db[96876] or {}
db[96876][db[96876]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Il mio zaino! Quando l'ho lasciato cadere per scappare da quel ragno enorme, pensavo che non l'avrei mai più rivisto. Sei davvero $Gun eroe:un'eroina;!",enHash={"7ea6a3f3"}}
db[96877]=db[96877] or {}
db[96877][db[96877]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sì?",enHash={"00388a38"}}
db[96877]=db[96877] or {}
db[96877][db[96877]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Che trofeo, $C! Dev'essere stato un bel combattimento!",enHash={"0928bb26"}}
db[96895]=db[96895] or {}
db[96895][db[96895]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Stai bass$Go:a; e cerca di non farti vedere, $C. Con questi cultisti non si scherza.",enHash={"a4d9752d"}}
db[96897]=db[96897] or {}
db[96897][db[96897]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Provo un disgusto particolare per i servitori viventi del Flagello. Hanno il libero arbitrio per andarsene, eppure la promessa di potere e immortalità li ha privati della ragione e della morale.",enHash={"9af7e60c"}}
db[96897]=db[96897] or {}
db[96897][db[96897]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grazie per il tuo aiuto, $C. Se non vogliamo che la storia di Lordaeron si ripeta, dobbiamo restare vigili quando spuntano minacce come questa.",enHash={"fce59358"}}
db[96898]=db[96898] or {}
db[96898][db[96898]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ti consiglio di non entrare troppo a contatto con quei cristalli. Anche frantumata ed esaurita, la magia residua in questi cristalli necrotici è estremamente pericolosa.",enHash={"84e46427"}}
db[96898]=db[96898] or {}
db[96898][db[96898]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grazie. Questo dovrebbe rallentare gli sforzi del Flagello in quest'area. Sospetto che gli abitanti di Tirisfal continueranno a estrarre questi cristalli dal terreno per anni, ma rimuovere i più vistosi non può che aiutare.",enHash={"23d0145c"}}
db[96899]=db[96899] or {}
db[96899][db[96899]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questo luogo è pieno di ricordi per me. Un tempo era tenuto dall'Argent Dawn. Fu da qui che ci preparammo per molte battaglie e schermaglie contro il Flagello durante la sua ultima avanzata nelle Tirisfal Glades.\n\nQuando ci ritirammo nelle Plaguelands temevo che sarebbe andato in rovina. Il mio timore era fondato, ma sono lieto che Danitha e i suoi paladini ne abbiano ora preso la custodia.\n\nHa persino dato alla fortezza il nome di... un amico comune.",enHash={"43df37f1"}}
db[96986]=db[96986] or {}
db[96986][db[96986]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ottimo lavoro. Quella bestia non è degna di camminare tra i morti. Che giaccia sotto di loro.",enHash={"6ab588ee"}}
db[97003]=db[97003] or {}
db[97003][db[97003]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ci è voluta la forza di sei combattenti esperti per sconfiggere una di queste creature, e prima che riuscissimo ad abbatterla è comunque riuscita a far cadere quattro di noi.\n\nSe queste bestie mostruose dovessero comparire in numero maggiore, i danni che i quilboar potrebbero infliggere alla terra sarebbero catastrofici.",enHash={"0e7c6e69"}}
db[97003]=db[97003] or {}
db[97003][db[97003]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Impressionante, $C. Nessuno dubiterà dei miei racconti quando tornerò a Orgrimmar con questa macabra prova dell'esistenza di questi abomini. Ma stai tranquill$Go:a;, la gloria è tua, e parlerò a gran voce delle tue imprese.\n\nLok-tar!",enHash={"c88df9f5"}}
db[97220]=db[97220] or {}
db[97220][db[97220]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Vuoi riempire una cassa con le nostre migliori forme stagionate?",enHash={"1b420d15"}}
db[97220]=db[97220] or {}
db[97220][db[97220]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oh, caro mio. Pensi che vogliamo portarla su per le scale da soli? Mantenere intatti i beni di valore è tua responsabilità fino al momento della consegna.",enHash={"541bc6f7"}}
db[97236]=db[97236] or {}
db[97236][db[97236]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Bene, bene. Quanto adoro le sorprese, $N.\n\nQuesto esemplare aiuterà sicuramente i miei studi.",enHash={"efc7870a"}}
db[97242]=db[97242] or {}
db[97242][db[97242]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Scopriamo formule e ricette mostrando vecchi ingredienti alle nuove generazioni, che li sperimentano a modo loro.",enHash={"d979bc9d"}}
db[97242]=db[97242] or {}
db[97242][db[97242]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Questo tipo di tifa e di erba lancia è unico di Orgrimmar. Abbeverate dall'acqua sorgiva delle montagne di Azshara e nutrite dalla polvere minerale della nostra terra rocciosa, intrisa di sudore e sangue, queste erbe racchiudono poteri potenti.\n\nLe darò a Yelmak, che forse con una lezione pratica riuscirà a riconquistare l'attenzione di Whuut.",enHash={"c9f10cba"}}
db[97246]=db[97246] or {}
db[97246][db[97246]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Certo. Io e i genitori di Migi abbiamo un accordo per dare a Migi un pranzo al sacco ogni giorno, ma posso assicurarmi che il ragazzo abbia il suo cibo solo se viene davvero a prenderlo.\n\nA volte non passa a prendere il pasto per più volte a settimana, e mi chiedo dove trovi l'energia per restare fuori a giocare.",enHash={"91fdbcc8"}}
db[97249]=db[97249] or {}
db[97249][db[97249]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Credo che questa possiamo vincerla...",enHash={"c1e96669"}}
db[97249]=db[97249] or {}
db[97249][db[97249]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Borstan's Meats? È per uno di noi?\n\nOh!\n\nWow... ha un profumo buonissimo! Gnam.\n\nGrazie per avermi portato il pranzo. Riesco a capire cosa servirà Borstan ogni giorno solo dagli odori, quando io e i miei amici percorriamo la strada verso Grommash Hold. Questo sa del mio preferito, il dolceglassato! Ma è diverso. Mi piacciono le briciole dal sapore forte.\n\nSe sarà così buono ogni giorno, credo che dovremo interrompere il nostro gioco per pranzare insieme!",enHash={"b7cd490a"}}
db[97250]=db[97250] or {}
db[97250][db[97250]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Allora le voci erano vere! Me l'aspettavo, le tensioni lungo la costa orientale crescono da tempo. Sapevo che era solo questione di tempo prima che il conflitto si insinuasse nel nostro territorio.\n\nTuttavia, dubito che abbiamo avuto un ruolo nella distruzione della taverna. Troppi civili dell'Orda dipendono da quella via per commerciare e viaggiare. Forse potresti indagare ancora, se trovi il tempo.\n\nIn ogni caso, l'impresa di oggi è una vittoria per l'Orda e un severo avvertimento per l'Alleanza!",enHash={"8d42d9e4"}}
db[97253]=db[97253] or {}
db[97253][db[97253]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Non una parola di più finché le tue tasche non tintinneranno di metallo!",enHash={"6e8951d0"}}
db[97253]=db[97253] or {}
db[97253][db[97253]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Wooooah! Bel colpo, amic$Go:a;! Mi hai risparmiato un'altra delle insopportabili lezioni di Gagsprocket sul costo del metallo. E soprattutto posso buttarmi subito a costruire il mio prossimo prototipo.\n\nEhm, non avevo previsto una ricompensa... Ti piacciono le scatole?",enHash={"820a2226"}}
db[97263]=db[97263] or {}
db[97263][db[97263]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cos'hai lì?",enHash={"dc90188f"}}
db[97263]=db[97263] or {}
db[97263][db[97263]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Cosa! Sono andato alla cassetta delle lettere vicino alla banca ogni giorno cercando questo pacco! Questa città deve sistemare la sua pianta. Non è facile orientarsi come ad Aerie Peak!\n\nVediamo cosa mi è arrivato... attrezzi per intagliare totem... un'ascia di scorta... una specie di congegno goblin? Questo non l'ho ordinato! Ah, lo rispedirò indietro.\n\nEhm, cioè... volevo dire... grazie per avermi portato tutto questo. Ecco qualcosina per il disturbo.",enHash={"c70c2e07"}}
db[97275]=db[97275] or {}
db[97275][db[97275]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Bene, cosa c'è dopo... Loto Nero, Salviargentea di Montagna...",enHash={"4024b094"}}
db[97275]=db[97275] or {}
db[97275][db[97275]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Grorru... cosa?\n\nDici che Yelmak ha preparato questa pozione con erba lancia e tifa, senza altri reagenti? Non sapevo che gli alchimisti avessero davvero bisogno di queste piante comuni che vediamo ogni giorno.\n\nForse ha ragione. Potrei perdermi molto passando subito alla flora più rara e meno studiata.\n\n$N, scegli una di queste pozioni che ho preparato prima. Ti ringrazio per aver trovato il tempo di visitare la nostra bottega.",enHash={"7864ff4b"}}
db[97281]=db[97281] or {}
db[97281][db[97281]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Wow, dove hai trovato un aggeggio così bello? Sai, mi ricorda quell'altra cosa che il mio capo Gazlowe mi diceva sempre...",enHash={"37fbe5d1"}}
db[97282]=db[97282] or {}
db[97282][db[97282]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Potrebbe sorprenderti che, con un nome come lucertola del tuono, sparino fulmini invece di ruggire come un tuono.\n\nBeh, lo fanno. Sparano fulmini, intendo.\n\nFidati, è una lezione che impari una volta sola, se ti va bene.",enHash={"c93292a0"}}
db[97282]=db[97282] or {}
db[97282][db[97282]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ehi, grazie amic$Go:a;! Mi hai dato davvero una grossa mano e te ne sono grato.\n\nSperiamo di riuscire a caricare tutto usando questi organi. Scommetto che farà pensare due volte quelle arpie buone a nulla prima di attaccare di nuovo la mia carovana. Spero proprio che funzioni.\n\nIn ogni caso hai fatto la tua parte dell'accordo. Prendi questo per il disturbo.",enHash={"d2b78968"}}
db[97288]=db[97288] or {}
db[97288][db[97288]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Cosa abbiamo qui?",enHash={"4fbe69d9"}}
db[97288]=db[97288] or {}
db[97288][db[97288]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Oho! Credo di conoscere questa testa. Uno scherzo crudele della nostra Dark Lady. E delizioso, per giunta.\n\nCredo di avere un uso per questa.",enHash={"93b836f9"}}
db[97289]=db[97289] or {}
db[97289][db[97289]["progress"] and "progress#wowhead20261030" or "progress"]= {it="<L'abominio resta senza vita, privo di una testa che lo controlli.>",enHash={"a977c5b2"}}
db[97289]=db[97289] or {}
db[97289][db[97289]["reward"] and "reward#wowhead20261030" or "reward"]= {it="<Il corpo si contorce tornando in vita, in preda al panico mentre rivive i suoi ultimi istanti.>\n\nTu...",enHash={"f5dd5e42"}}
db[97290]=db[97290] or {}
db[97290][db[97290]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Non collabora, eh? Eccellente. Adoro le sfide.",enHash={"61921c06"}}
db[97291]=db[97291] or {}
db[97291][db[97291]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sarà davvero delizioso riavere all'ovile la nostra pecorella smarrita, non credi?",enHash={"44c16bd5"}}
db[97291]=db[97291] or {}
db[97291][db[97291]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Andranno benissimo. Vedremo quanta spavalderia conserverà il nostro illustre ospite dopo essere stato sottoposto al mio capolavoro.",enHash={"4e172e35"}}
db[97292]=db[97292] or {}
db[97292][db[97292]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Per i crimini di Othmar contro la Dark Lady, metterlo sotto quell'esemplare trasudante è il minimo che si meriti.\n\nE la cosa buffa è...",enHash={"8d685f66"}}
db[97292]=db[97292] or {}
db[97292][db[97292]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Eccellente. Lasceremo cuocere a fuoco lento la sua carne per un po'. Diamogli il tempo di abituarsi alla sua nuova casa.\n\nPer ora non ho più bisogno di quel disgraziato, ma lo terremo d'occhio. Ho molti piani per il futuro di Othmar.",enHash={"66e97429"}}
db[97326]=db[97326] or {}
db[97326][db[97326]["progress"] and "progress#wowhead20261030" or "progress"]= {it="È bello non doversi sempre sedere nella polvere!",enHash={"8a093d7e"}}
db[97326]=db[97326] or {}
db[97326][db[97326]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ma come fai a reggere tutti quei massi!\n\nSono fantastici. La maggior parte ha anche un bel lato piatto. Ora che li hai portati fin qui, possiamo spostarli nella polvere proprio dove li vogliamo.\n\nGrazie, $N!",enHash={"83dd2e18"}}
db[97485]=db[97485] or {}
db[97485][db[97485]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Ci sono molte occasioni in cui si può scegliere di spargere incenso ai venti. Potresti chiedere alla Earthmother di vegliare su qualcuno, benedire una caccia, celebrare un evento o persino cercare la guida dei nostri antenati.\n\nOppure potrebbe trattarsi di tutt'altro.\n\nAnche se il gesto si compie con reverenza, non è un atto strettamente cerimoniale. Di solito si seguono alcuni passaggi tradizionali, ma molte tribù hanno usanze diverse.",enHash={"df1284e9"}}
db[97485]=db[97485] or {}
db[97485][db[97485]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Hai fatto bene, amic$Go:a;.\n\nTi ringrazio per aver trovato il tempo di compiere una delle nostre antiche tradizioni, $N. Spero che nei tuoi viaggi troverai molte occasioni per cui voler rendere grazie.\n\nSe mai volessi ripetere il rituale, dovresti poter riacquistare i componenti che ti ho mandato a raccogliere.\n\nVa' con il calore di An'she.",enHash={"0b297f5d"}}
db[97538]=db[97538] or {}
db[97538][db[97538]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sei tornat$Go:a;! Sei riuscit$Go:a; a trovare i baccelli della pianta di mirkweed nel Mirkfallon Lake?\n\nNoi tauren usiamo questo pigmento vegetale nelle nostre pitture da generazioni, quindi qualunque quantità tu riesca a portare sarà apprezzata. Anche se ci sono molti modi per ottenere un pigmento rosso, tra i metodi che conosco trovo che il mirkweed dia la tonalità più ricca e vivace.",enHash={"77bb9ad5"}}
db[97538]=db[97538] or {}
db[97538][db[97538]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ah, grazie, $N.\n\nSignifica molto per me che tu ti sia avventurat$Go:a; fin laggiù per quella che deve sembrare una fissazione da poco di un vecchio tauren, ma grazie alla tua gentilezza avrò pigmento a sufficienza per il resto della stagione.\n\nGrazie per aver sostenuto il mio lavoro: mi impegnerò a creare qualcosa di magnifico con i pigmenti che mi hai portato.",enHash={"0ee431f2"}}
db[97558]=db[97558] or {}
db[97558][db[97558]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Hai raccolto la pelle che ti ho chiesto? Le nostre scorte si stanno esaurendo.\n\nPuò sembrare strano chiedere pelle di murloc, ma funziona bene per le membrane interne, o per superfici come guance e bocche.\n\nAllo stesso modo, le membrane delle ali di duskbat sono particolarmente adatte alle zone più delicate, come volti o dita. Evitano che la pelle risulti troppo... spessa.",enHash={"7eae48f8"}}
db[97558]=db[97558] or {}
db[97558][db[97558]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ah, eccellente! Grazie per esserteli procurati. Ti prometto che saranno usati bene.",enHash={"0ef184f1"}}
db[97900]=db[97900] or {}
db[97900][db[97900]["progress"] and "progress#wowhead20261030" or "progress"]= {it="Sì, posso insegnarti.",enHash={"b1aadc3c"}}
db[97900]=db[97900] or {}
db[97900][db[97900]["reward"] and "reward#wowhead20261030" or "reward"]= {it="Ecco fatto, ora puoi creare il tuo Sharpening Wheel. Alla maggior parte della gente non piace che si allestiscano accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. La maggior parte dei cuochi può insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa addestrarti nell'arte culinaria per imparare le basi.",enHash={"d830891b"}}
db[97901]=db[97901] or {}
